<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    * { box-sizing: border-box; }
    body { margin: 0; font: 16px/1.5 system-ui, sans-serif; color: #17212b; background: #f5f7fa; }
    main { max-width: 760px; margin: 48px auto; padding: 0 24px; }
    h1 { margin: 0 0 24px; font-size: 2rem; }
    form { display: flex; align-items: end; gap: 12px; margin-bottom: 24px; }
    label { display: grid; gap: 6px; flex: 1; font-weight: 600; }
    input { min-height: 42px; padding: 8px 10px; border: 1px solid #8795a1; border-radius: 5px; font: inherit; }
    button { min-height: 42px; padding: 8px 16px; border: 0; border-radius: 5px; color: white; background: #175fc1; font: inherit; cursor: pointer; }
    button:hover { background: #104a99; }
    #alert { color: #a51c30; margin: 0 0 16px; }
    #alert:empty { display: none; }
    #projects { display: grid; gap: 10px; }
    .project-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 14px 16px; background: white; border: 1px solid #d9e0e6; border-radius: 6px; }
    @media (max-width: 520px) { main { margin-top: 28px; } form { align-items: stretch; flex-direction: column; } }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const path = location.pathname;
    const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const projects = await fetch('/api/projects').then(r => r.json());
    if (path.startsWith('/projects/')) {
      const id = decodeURIComponent(path.slice('/projects/'.length));
      const project = projects.find(item => String(item.id) === id);
      app.innerHTML = `<button type="button" id="back">Projects</button><h1>${project ? escapeHtml(project.name) : 'Project not found'}</h1>`;
      document.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
    } else {
      app.innerHTML = `<h1>Workboard</h1>
        <form id="create-form"><label for="project-name">Project name</label><input id="project-name" name="name" type="text" aria-label="Project name"><button type="submit">Create project</button></form>
        <p id="alert" role="alert" aria-live="polite"></p><section id="projects" aria-label="Projects"></section>`;
      const list = document.querySelector('#projects');
      const alert = document.querySelector('#alert');
      function render() {
        list.innerHTML = projects.map(project => `<div class="project-row" data-testid="project-row"><span>${escapeHtml(project.name)}</span><button type="button" data-id="${project.id}">Open project</button></div>`).join('');
        list.querySelectorAll('button').forEach(button => button.addEventListener('click', () => { location.href = `/projects/${encodeURIComponent(button.dataset.id)}`; }));
      }
      render();
      document.querySelector('#create-form').addEventListener('submit', async event => {
        event.preventDefault();
        const input = document.querySelector('#project-name');
        const name = input.value.trim();
        if (!name) { alert.textContent = 'Project name is required'; return; }
        const response = await fetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
        if (!response.ok) { alert.textContent = 'Project name is required'; return; }
        projects.push(await response.json());
        input.value = '';
        alert.textContent = '';
        render();
      });
    }
  </script>
</body>
</html>
